const base = $('Prepare Personalized Outreach').first().json;
const telegram = $input.first().json;
return [{ json: {
  ...base,
  approval: base.approval || { required: false, approved: true, raw_status: 'not_required' },
  delivery: {
    mode: 'live',
    email_status: 'sent',
    sales_alert_status: telegram.ok === false || telegram.error ? 'failed' : 'sent',
    recipient: base.lead.email
  }
} }];

const base = $('Prepare Personalized Outreach').first().json;
return [{ json: {
  ...base,
  approval: base.approval || { required: false, approved: true, raw_status: 'not_required' },
  delivery: { mode: 'live', email_status: 'sent', sales_alert_status: 'not_required', recipient: base.lead.email }
} }];

const data = $input.first().json;
return [{ json: {
  ...data,
  approval: data.approval || { required: false, approved: true, raw_status: 'not_required' },
  delivery: {
    mode: 'live',
    email_status: 'not_sent_cold_nurture',
    sales_alert_status: 'not_required',
    nurture_status: 'queued',
    suggested_follow_up_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString()
  }
} }];

const data = $input.first().json;
if (!data.config.demo_mode) {
  const store = $getWorkflowStaticData('global');
  store.revenueflow_leads = store.revenueflow_leads || {};
  store.revenueflow_leads[data.identity.fingerprint] = {
    status: 'completed',
    request_id: data.request_meta.request_id,
    tier: data.scoring.tier,
    score: data.scoring.total,
    updated_at: Date.now()
  };
  store.revenueflow_metrics = store.revenueflow_metrics || {};
  const day = new Date().toISOString().slice(0, 10);
  store.revenueflow_metrics[day] = store.revenueflow_metrics[day] || { total: 0, hot: 0, warm: 0, cold: 0, duplicates: 0 };
  store.revenueflow_metrics[day].total += 1;
  store.revenueflow_metrics[day][data.scoring.tier] += 1;
}

return [{ json: {
  success: true,
  status: data.config.demo_mode ? 'demo_completed' : 'completed',
  request_id: data.request_meta.request_id,
  lead_id: data.identity.fingerprint,
  lead: {
    name: `${data.lead.first_name} ${data.lead.last_name}`.trim(),
    company: data.lead.company,
    email: data.lead.email
  },
  score: data.scoring.total,
  tier: data.scoring.tier,
  priority: data.scoring.priority,
  score_breakdown: data.scoring.breakdown,
  assessment: {
    summary: data.ai_assessment.summary,
    recommended_action: data.ai_assessment.recommended_action,
    provider: data.intelligence_meta.provider,
    fallback_used: data.intelligence_meta.fallback_used
  },
  crm: data.crm,
  approval: data.approval,
  delivery: data.delivery,
  processed_at: new Date().toISOString()
} }];
